// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        bytes32 role = keccak256("PROPOSER_ROLE");
        c.grantRole(role, address(this));
        bytes32 id = c.hashOperation(address(0), 0, "", bytes32(0), bytes32(0));
        c.schedule(address(0), 0, "", bytes32(0), bytes32(0), 0);
        c.cancel(id);
        bytes4 interfaceId = type(IAccessControl).interfaceId;
        bool result = c.supportsInterface(interfaceId);
        assertTrue(result == true, "supportsInterface should return true");
    }
}

