pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        c.schedule(target, value, data, predecessor, salt, 0);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Cancel the operation
        c.cancel(id);

        // Check supportsInterface for IAccessControl interfaceId
        bytes4 interfaceId = bytes4(keccak256("supportsInterface(bytes4)"));
        // Actually use the IAccessControl interface ID: 0x7965db0b
        bytes4 accessControlInterfaceId = 0x7965db0b;
        bool result = c.supportsInterface(accessControlInterfaceId);

        // Reference: supportsInterface should return true because AccessControl implements IAccessControl
        // Buggy version always returns true
        // Both return true, so this doesn't differentiate. Let's use a non-existent interface ID.
        // Use ID that is NOT IERC165 or IAccessControl, e.g. 0x01ffc9a7 is IERC165, 0x7965db0b is IAccessControl
        // Let's use 0xffffffff
        bytes4 nonExistentInterfaceId = 0xffffffff;
        bool result2 = c.supportsInterface(nonExistentInterfaceId);

        // Reference: returns false for non-existent interface; Bug: returns true
        assertTrue(result2 == false, "Buggy version always returns true, reference returns false");
    }
}

