pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        // Schedule an operation
        bytes32 id = c.hashOperation(address(0xdead), 0, hex"00", bytes32(0), bytes32(0x1234));
        c.schedule(address(0xdead), 0, hex"00", bytes32(0), bytes32(0x1234), 1);
        // Warp past the delay to make operation ready
        vm.warp(block.timestamp + 1);
        // Cancel the operation
        c.cancel(id);
        // Now check supportsInterface for the ERC165 interfaceId (0x01ffc9a7)
        // Reference returns false (not IAccessControl, only ERC165 supports its own id)
        // Bug returns true
        assertTrue(c.supportsInterface(0x01ffc9a7) == false, "supportsInterface(0x01ffc9a7) should be false in reference");
    }
}

