// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testRegression_property() public {
        bytes32 id = keccak256(abi.encode(address(0), 0, hex"", bytes32(0), bytes32(0)));
        c.schedule(address(0), 0, hex"", bytes32(0), bytes32(0), 0);
        vm.warp(block.timestamp + 1);
        c.execute(address(0), 0, hex"", bytes32(0), bytes32(0));
        // Now cancel a non-pending operation to trigger the revert path
        vm.expectRevert("TimelockController: operation cannot be cancelled");
        c.cancel(id);
        // After cancel revert, check supportsInterface for IAccessControl
        bool result = c.supportsInterface(0x7965db0b);
        assertTrue(result);
    }
}

